select m1_0.match_id,m1_0.match_time,m1_0.sets,s1_0.name,s1_0.is_regular,t1_0.team_id,t1_0.code,sum(case when ts1_0.victory=true then 1 else 0 end),count(ts1_0.team_set_id) from team_set ts1_0 join match_set ms1_0 on ms1_0.set_id=ts1_0.set_id join lck_match m1_0 on m1_0.match_id=ms1_0.match_id join stage s1_0 on s1_0.stage_id=m1_0.stage_id join team t1_0 on t1_0.team_id=ts1_0.team_id group by m1_0.match_id,m1_0.match_time,m1_0.sets,s1_0.name,s1_0.is_regular,t1_0.team_id,t1_0.code
